using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class EvalTests : EvalTestBase
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void ClassInitialize(TestContext context)
    {
        s_reportingConfiguration = ConfigureReporting(nameof(EvalTests));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task ChatRespondsRelevantly()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            TestContext.TestName!);

        var chatClient = GetChatClient(scenario);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = new IEvaluator[]
        {
            new RelevancyEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator()
        };

        await scenario.EvaluateAsync(messages, evaluators);
    }
}

using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

public abstract class EvalTestBase
{
    public TestContext TestContext { get; set; } = default!;

    private static DistributedApplicationTestingBuilder? s_appHost;
    private static DistributedApplication? s_app;

    [AssemblyInitialize]
    public static async Task AssemblyInitialize(TestContext context)
    {
        s_appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        s_app = await s_appHost.BuildAsync();
        await s_app.StartAsync();
    }

    [AssemblyCleanup]
    public static async Task AssemblyCleanup()
    {
        if (s_app is not null)
        {
            await s_app.StopAsync();
            await s_app.DisposeAsync();
        }
    }

    protected static ReportingConfiguration ConfigureReporting(string testClassName)
    {
        var storagePath = Path.Combine(
            Path.GetTempPath(), "MyApp.Evals", "reports");

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: storagePath,
            executionName: testClassName,
            chatConfiguration: ChatConfiguration.Default);
    }

    protected static IChatClient GetChatClient(ScenarioRun scenarioRun)
    {
        return scenarioRun.ChatConfiguration!.ChatClient
            ?? s_app!.Services.GetRequiredService<IChatClient>();
    }
}

